-- Armor batch 2026-10-22 (Codex/Cap, approved by Gabriel). Idempotent.
BEGIN;
-- Requires armor_con_cap_2026_10_22.sql (dex_cap -> con_cap) on databases created before that rename.
ALTER TABLE armor ADD COLUMN IF NOT EXISTS properties jsonb NULL;
-- Normalise rarity casing (e.g. 'common' -> 'Common') so the check and the client filter match.
UPDATE armor SET rarity = initcap(rarity) WHERE rarity IS NOT NULL AND rarity <> initcap(rarity);
-- The 28 original (pre-batch) armor rows are Common; fill any left NULL.
UPDATE armor SET rarity = 'Common' WHERE rarity IS NULL AND id IN (SELECT id FROM armor ORDER BY id LIMIT 28);
ALTER TABLE armor DROP CONSTRAINT IF EXISTS armor_rarity_check;
ALTER TABLE armor ADD CONSTRAINT armor_rarity_check CHECK (rarity IS NULL OR rarity IN ('Common','Magical','Arcane','Mythical','Blessed'));
INSERT INTO armor (name, armor_type, ac_bonus, con_cap, stealth_disadvantage, strength_req, description, rarity, properties)
SELECT r.name, r.armor_type, r.ac_bonus, r.con_cap, r.stealth_disadvantage, r.strength_req, r.description, r.rarity, r.properties
FROM jsonb_to_recordset($armor$[{"name": "Ochrehide Jerkin", "armor_type": "light", "ac_bonus": 2, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Tanned hide stained with Ochre clay; a road-warden staple.", "rarity": "Common", "properties": null}, {"name": "Lupine Trailcoat", "armor_type": "light", "ac_bonus": 2, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Fur-trimmed leather cut for long runs in Lupine country.", "rarity": "Common", "properties": null}, {"name": "Vellari Gauze Wrap", "armor_type": "light", "ac_bonus": 1, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Layered gauze bands the Vellari wear under travel robes.", "rarity": "Common", "properties": null}, {"name": "Sablethread Doublet", "armor_type": "light", "ac_bonus": 2, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Black quilted doublet with corded seams.", "rarity": "Common", "properties": null}, {"name": "Graniar Quarry Apron", "armor_type": "light", "ac_bonus": 1, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Heavy canvas apron with slate inserts, worn by Graniar cutters.", "rarity": "Common", "properties": null}, {"name": "Skyborn Gliding Leathers", "armor_type": "light", "ac_bonus": 2, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Close-fitted leathers with webbed underarms.", "rarity": "Common", "properties": null}, {"name": "Dewlight Jerkin", "armor_type": "light", "ac_bonus": 3, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Pale leather that beads with dew at dawn. Once per long rest, when you would be blinded, you can use your reaction to ignore it until the end of your next turn.", "rarity": "Magical", "properties": {"condition_ignore": ["blinded"], "uses": "1/long rest", "action_type": "reaction"}}, {"name": "Cinderfoot Leathers", "armor_type": "light", "ac_bonus": 3, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Soot-dark leather from the Gehennan borderlands. You take no damage from walking on hot ground, embers or burning terrain, and you have advantage on saves against being knocked prone.", "rarity": "Magical", "properties": {"terrain_immune": ["burning"], "save_advantage": ["prone"]}}, {"name": "Whisperstep Vest", "armor_type": "light", "ac_bonus": 2, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Felted vest that drinks sound. Opportunity attacks against you are made with disadvantage if you moved at least 10 ft this turn.", "rarity": "Magical", "properties": {"oa_disadvantage_if_moved_ft": 10}}, {"name": "Thornmoss Wrap", "armor_type": "light", "ac_bonus": 3, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Living moss over leather; it prickles when grabbed. When a creature grapples you, it takes 1d4 piercing damage.", "rarity": "Magical", "properties": {"retaliate": {"trigger": "grappled", "dice": "1d4", "type": "piercing"}}}, {"name": "Umbral Veilcoat", "armor_type": "light", "ac_bonus": 3, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Umber-dyed silk that pools with shadow. While in dim light or darkness you can take the Hide action as a bonus action. Once per short rest, when hit, you can use your reaction to become heavily obscured to that attacker until the start of your next turn (it has disadvantage on further attacks).", "rarity": "Arcane", "properties": {"bonus_action": "hide_in_dim", "uses": "1/short rest", "action_type": "reaction"}}, {"name": "Moonfeather Mantle", "armor_type": "light", "ac_bonus": 3, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Skyborn flight-feathers sewn over a leather spine. You take no falling damage from falls of 60 ft or less, and once per long rest you can glide: for 1 minute you descend 60 ft per round and move 2 ft horizontally per 1 ft fallen.", "rarity": "Arcane", "properties": {"fall_immune_ft": 60, "uses": "1/long rest"}}, {"name": "Ochre Drifter's Coat", "armor_type": "light", "ac_bonus": 4, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Dust-coloured greatcoat that seems to blur at the hem. Your walking speed can't be reduced by difficult terrain made of sand, mud or snow, and once per short rest you can take the Dash action as a bonus action.", "rarity": "Arcane", "properties": {"ignore_terrain": ["sand", "mud", "snow"], "uses": "1/short rest", "action_type": "bonus action"}}, {"name": "Radiant Dawnweave", "armor_type": "light", "ac_bonus": 4, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Gold-white cloth woven by Radiant hands. Twice per long rest, when an ally within 30 ft takes damage, you can use your reaction to take half of it instead. You can't be charmed while conscious.", "rarity": "Mythical", "properties": {"redirect_damage": {"range_ft": 30, "portion": "half"}, "uses": "2/long rest", "action_type": "reaction", "condition_immune": ["charmed"]}}, {"name": "Sable Nightskin", "armor_type": "light", "ac_bonus": 4, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Supple armor of sable-black hide that never reflects light. Ranged attacks against you have disadvantage while you are more than 30 ft from the attacker.", "rarity": "Mythical", "properties": {"ranged_disadvantage_beyond_ft": 30}}, {"name": "Vestment of the First Dawn", "armor_type": "light", "ac_bonus": 5, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Said to have been worn before the Ochre sky first broke. You have resistance to necrotic and radiant damage. Once per long rest, as a bonus action, you shed dawnlight for 1 minute: you and allies within 10 ft regain HP equal to your proficiency bonus at the start of each of your turns, and can't be frightened.", "rarity": "Blessed", "properties": {"resist": ["necrotic", "radiant"], "regen_aura": {"range_ft": 10, "amount": "proficiency", "duration": "1 minute"}, "condition_immune_aura": ["frightened"], "uses": "1/long rest", "action_type": "bonus action"}}, {"name": "Lupine Ridgehide", "armor_type": "medium", "ac_bonus": 3, "con_cap": 2, "stealth_disadvantage": false, "strength_req": null, "description": "Layered wolf-hide with a raised spine ridge.", "rarity": "Common", "properties": null}, {"name": "Graniar Slate Lamellar", "armor_type": "medium", "ac_bonus": 4, "con_cap": 2, "stealth_disadvantage": true, "strength_req": null, "description": "Thin slate plates laced in rows; it clacks.", "rarity": "Common", "properties": null}, {"name": "Umberwood Scale", "armor_type": "medium", "ac_bonus": 4, "con_cap": 2, "stealth_disadvantage": true, "strength_req": null, "description": "Hardened dark-wood scales over leather.", "rarity": "Common", "properties": null}, {"name": "Vellari Lacquered Coat", "armor_type": "medium", "ac_bonus": 3, "con_cap": 2, "stealth_disadvantage": false, "strength_req": null, "description": "Lacquered panels on a Vellari riding coat.", "rarity": "Common", "properties": null}, {"name": "Ochre Clay Cuirass", "armor_type": "medium", "ac_bonus": 5, "con_cap": 2, "stealth_disadvantage": true, "strength_req": 12, "description": "Fired-clay breastplate on a padded backing.", "rarity": "Common", "properties": null}, {"name": "Marchwarden Brigandine", "armor_type": "medium", "ac_bonus": 5, "con_cap": 2, "stealth_disadvantage": true, "strength_req": 12, "description": "Canvas-covered plates riveted for border patrols.", "rarity": "Common", "properties": null}, {"name": "Saltglass Scale", "armor_type": "medium", "ac_bonus": 4, "con_cap": 2, "stealth_disadvantage": true, "strength_req": null, "description": "Scales of fused coastal glass. You have resistance to acid damage from every source, and advantage on saves against being poisoned.", "rarity": "Magical", "properties": {"resist": ["acid"], "save_advantage": ["poisoned"]}}, {"name": "Stormhide Lamellar", "armor_type": "medium", "ac_bonus": 5, "con_cap": 2, "stealth_disadvantage": true, "strength_req": 12, "description": "Hide plates from beasts of the high storms. When you are hit by a lightning attack, you can halve the damage (reaction, 1/short rest).", "rarity": "Magical", "properties": {"halve_damage": ["lightning"], "uses": "1/short rest", "action_type": "reaction"}}, {"name": "Bramblewarden Coat", "armor_type": "medium", "ac_bonus": 4, "con_cap": 2, "stealth_disadvantage": false, "strength_req": null, "description": "Woven bramble over hide; it shifts like a hedge. You can't be pushed or pulled more than 5 ft against your will.", "rarity": "Magical", "properties": {"forced_move_max_ft": 5}}, {"name": "Hearthcoal Brigandine", "armor_type": "medium", "ac_bonus": 5, "con_cap": 2, "stealth_disadvantage": true, "strength_req": 12, "description": "Plates warmed from within by a coal-red lining. You suffer no penalties from extreme cold, and once per long rest you can end the frightened condition on yourself as a bonus action.", "rarity": "Magical", "properties": {"env_immune": ["cold"], "uses": "1/long rest", "action_type": "bonus action"}}, {"name": "Gehennan Ashscale", "armor_type": "medium", "ac_bonus": 5, "con_cap": 2, "stealth_disadvantage": true, "strength_req": 12, "description": "Grey scales that flake like cooled ash. You have resistance to fire damage. When a creature hits you with a melee attack while you are bloodied, it takes fire damage equal to your proficiency bonus.", "rarity": "Arcane", "properties": {"resist": ["fire"], "retaliate": {"trigger": "melee_hit_while_bloodied", "amount": "proficiency", "type": "fire"}}}, {"name": "Skyborn Windcuirass", "armor_type": "medium", "ac_bonus": 5, "con_cap": 2, "stealth_disadvantage": false, "strength_req": 12, "description": "Light cuirass vented with feather-shaped slits. You have advantage on Stealth checks. Once per long rest, as a bonus action, you become invisible until the end of your next turn or until you attack.", "rarity": "Arcane", "properties": {"skill_advantage": ["Stealth"], "uses": "1/long rest", "action_type": "bonus action"}}, {"name": "Umber Mirecoat", "armor_type": "medium", "ac_bonus": 5, "con_cap": 2, "stealth_disadvantage": false, "strength_req": null, "description": "Dark oilcloth plates that shed water and grime. You have advantage on saves against being restrained or grappled, and once per short rest you can use a bonus action to escape a grapple automatically.", "rarity": "Arcane", "properties": {"save_advantage": ["restrained", "grappled"], "uses": "1/short rest", "action_type": "bonus action"}}, {"name": "Sable Wolfguard Harness", "armor_type": "medium", "ac_bonus": 6, "con_cap": 2, "stealth_disadvantage": false, "strength_req": 13, "description": "Lupine war-harness of sable steel and fur. While an ally is within 5 ft of you, you and that ally gain +1 to saving throws. Once per long rest, as a reaction to a crit against you, turn it into a normal hit.", "rarity": "Mythical", "properties": {"save_bonus_aura": {"range_ft": 5, "bonus": 1}, "crit_negate": true, "uses": "1/long rest", "action_type": "reaction"}}, {"name": "Ochre Sunscale", "armor_type": "medium", "ac_bonus": 6, "con_cap": 2, "stealth_disadvantage": true, "strength_req": 13, "description": "Burnished scales the colour of an Ochre noon. Twice per long rest, as a reaction when hit, you flare: the attacker is blinded until the end of its next turn (CON save vs 8 + proficiency + CON).", "rarity": "Mythical", "properties": {"on_hit_effect": {"condition": "blinded", "save": "CON"}, "uses": "2/long rest", "action_type": "reaction"}}, {"name": "Coat of the Unbroken Pack", "armor_type": "medium", "ac_bonus": 7, "con_cap": 2, "stealth_disadvantage": false, "strength_req": 13, "description": "Hide of the first Lupine pack-mother, never pierced. You have resistance to bludgeoning, piercing and slashing damage while bloodied. Once per long rest, as a bonus action, allies within 30 ft gain temporary HP equal to your level.", "rarity": "Blessed", "properties": {"resist_while_bloodied": ["bludgeoning", "piercing", "slashing"], "temp_hp_aura": {"range_ft": 30, "amount": "level"}, "uses": "1/long rest", "action_type": "bonus action"}}, {"name": "Graniar Stoneplate", "armor_type": "heavy", "ac_bonus": 6, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 15, "description": "Hammered plates backed with flat stone, Graniar-made.", "rarity": "Common", "properties": null}, {"name": "Sable Iron Hauberk", "armor_type": "heavy", "ac_bonus": 5, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 13, "description": "Blackened iron mail to the shin.", "rarity": "Common", "properties": null}, {"name": "Ochre Bulwark Harness", "armor_type": "heavy", "ac_bonus": 7, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 16, "description": "Thick ochre-painted plate for siege lines.", "rarity": "Common", "properties": null}, {"name": "Gehenna Slag Mail", "armor_type": "heavy", "ac_bonus": 6, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 14, "description": "Rings drawn from Gehennan slag; heavy and coarse.", "rarity": "Common", "properties": null}, {"name": "Umber Banded Coat", "armor_type": "heavy", "ac_bonus": 5, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 13, "description": "Banded iron strips over dark leather.", "rarity": "Common", "properties": null}, {"name": "Vellari Gatewarden Plate", "armor_type": "heavy", "ac_bonus": 6, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 15, "description": "Ceremonial plate of the Vellari gate guards.", "rarity": "Common", "properties": null}, {"name": "Ironroot Splint", "armor_type": "heavy", "ac_bonus": 7, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 15, "description": "Splints grown from iron-hard roots. You have advantage on saves against being knocked prone or pushed.", "rarity": "Magical", "properties": {"save_advantage": ["prone", "pushed"]}}, {"name": "Bellwether Plate", "armor_type": "heavy", "ac_bonus": 7, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 15, "description": "Plate with a small bronze bell at the gorget. As a bonus action (1/short rest), each enemy within 10 ft must make a WIS save or have disadvantage on attacks against creatures other than you until your next turn.", "rarity": "Magical", "properties": {"taunt": {"range_ft": 10, "save": "WIS"}, "uses": "1/short rest", "action_type": "bonus action"}}, {"name": "Frostfen Hauberk", "armor_type": "heavy", "ac_bonus": 6, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 14, "description": "Mail rimed with frost that never melts. You suffer no penalties from extreme cold and you can't be slowed by ice or snow.", "rarity": "Magical", "properties": {"env_immune": ["cold"], "ignore_terrain": ["ice", "snow"]}}, {"name": "Cragwall Carapace", "armor_type": "heavy", "ac_bonus": 7, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 16, "description": "Rough Graniar granite plates. When you take the Dodge action you also gain temporary HP equal to your CON modifier.", "rarity": "Magical", "properties": {"on_dodge_temp_hp": "CON"}}, {"name": "Gehennan Furnaceplate", "armor_type": "heavy", "ac_bonus": 8, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 16, "description": "Plate that glows dull red at the joints. Resistance to fire damage. Once per long rest, as an action, you vent heat: creatures within 10 ft make a DEX save (8 + proficiency + CON) or take 3d6 fire damage, half on a success.", "rarity": "Arcane", "properties": {"resist": ["fire"], "burst": {"range_ft": 10, "dice": "3d6", "type": "fire", "save": "DEX"}, "uses": "1/long rest", "action_type": "action"}}, {"name": "Sable Vigil Plate", "armor_type": "heavy", "ac_bonus": 8, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 15, "description": "Black plate whose wearer never sleeps deeply. You can't be surprised, and you have advantage on initiative.", "rarity": "Arcane", "properties": {"surprise_immune": true, "initiative_advantage": true}}, {"name": "Umbercrown Harness", "armor_type": "heavy", "ac_bonus": 7, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 15, "description": "Plate crowned with umber horns at the pauldrons. Once per short rest, when an ally within 5 ft is hit, you can use your reaction to become the target instead.", "rarity": "Arcane", "properties": {"intercept": {"range_ft": 5}, "uses": "1/short rest", "action_type": "reaction"}}, {"name": "Graniar Mountainheart", "armor_type": "heavy", "ac_bonus": 9, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 17, "description": "Plate carved from a single seam of mountain ore. You can't be moved against your will, and once per long rest you can reduce damage from one hit to 0 (reaction).", "rarity": "Mythical", "properties": {"forced_move_immune": true, "negate_hit": true, "uses": "1/long rest", "action_type": "reaction"}}, {"name": "Radiant Lanternplate", "armor_type": "heavy", "ac_bonus": 9, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 16, "description": "White-gold plate that hums with a held breath of light. Allies within 10 ft have advantage on saves against being frightened. Twice per long rest, as a reaction when an ally within 10 ft takes damage, they gain temporary HP equal to your level before the damage applies.", "rarity": "Mythical", "properties": {"aura_save_advantage": {"range_ft": 10, "conditions": ["frightened"]}, "ally_temp_hp_reaction": {"range_ft": 10, "amount": "level"}, "uses": "2/long rest", "action_type": "reaction"}}, {"name": "Aegis of the Last Ember", "armor_type": "heavy", "ac_bonus": 10, "con_cap": 0, "stealth_disadvantage": true, "strength_req": 17, "description": "Plate said to hold the final ember of a fallen sun. Resistance to radiant and necrotic damage. Once per long rest, when you are reduced below half HP, you regain HP equal to twice your level and enemies within 10 ft are pushed 10 ft.", "rarity": "Blessed", "properties": {"resist": ["radiant", "necrotic"], "heal_trigger": {"threshold": "half", "amount": "2x level"}, "uses": "1/long rest"}}, {"name": "Lupine Hide Targe", "armor_type": "shield", "ac_bonus": 1, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Round hide shield on a bent-wood frame.", "rarity": "Common", "properties": null}, {"name": "Graniar Slab Shield", "armor_type": "shield", "ac_bonus": 3, "con_cap": null, "stealth_disadvantage": true, "strength_req": 14, "description": "A cut slab of stone with a strap; brutal to carry.", "rarity": "Common", "properties": null}, {"name": "Ochre Oval Shield", "armor_type": "shield", "ac_bonus": 2, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Painted oval shield of ochre-dyed planks.", "rarity": "Common", "properties": null}, {"name": "Umber Ironrim Shield", "armor_type": "shield", "ac_bonus": 2, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Dark oak shield bound in iron.", "rarity": "Common", "properties": null}, {"name": "Skyborn Wingbuckler", "armor_type": "shield", "ac_bonus": 1, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Feather-shaped buckler of light bone.", "rarity": "Common", "properties": null}, {"name": "Vellari Crescent Shield", "armor_type": "shield", "ac_bonus": 2, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Crescent-cut shield used by Vellari cavalry.", "rarity": "Common", "properties": null}, {"name": "Thornback Buckler", "armor_type": "shield", "ac_bonus": 2, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Buckler grown from a briar knot. When a creature misses you with a melee attack, it takes 1d4 piercing damage (1/turn).", "rarity": "Magical", "properties": {"retaliate": {"trigger": "melee_miss", "dice": "1d4", "type": "piercing", "limit": "1/turn"}}}, {"name": "Tidewall Shield", "armor_type": "shield", "ac_bonus": 2, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Blue-lacquered shield that sheds water. You have advantage on DEX saves against effects you can see while this shield is raised.", "rarity": "Magical", "properties": {"save_advantage": ["DEX"]}}, {"name": "Sable Hushguard", "armor_type": "shield", "ac_bonus": 2, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Felt-faced black shield; blows land dull. Once per short rest, when hit by a critical hit, you can use your reaction to reduce the damage by 1d8.", "rarity": "Magical", "properties": {"reduce_damage": "1d8", "uses": "1/short rest", "action_type": "reaction"}}, {"name": "Bastion Pavise", "armor_type": "shield", "ac_bonus": 3, "con_cap": null, "stealth_disadvantage": true, "strength_req": 13, "description": "Tall standing shield with a fold-out brace. As a bonus action you can plant it: until you move, you and one adjacent ally gain half cover.", "rarity": "Magical", "properties": {"plant_cover": "half", "action_type": "bonus action"}}, {"name": "Gehennan Brandshield", "armor_type": "shield", "ac_bonus": 3, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Iron face scorched with a Gehennan mark. Once per short rest, when you block with your reaction, the attacker takes 2d6 fire damage.", "rarity": "Arcane", "properties": {"retaliate": {"trigger": "reaction_block", "dice": "2d6", "type": "fire"}, "uses": "1/short rest", "action_type": "reaction"}}, {"name": "Umber Eclipse Targe", "armor_type": "shield", "ac_bonus": 3, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Round shield with a dark disc that swallows light. Once per long rest, as a reaction to a spell attack or a spell that requires a DEX save, you gain +5 AC and advantage on that save.", "rarity": "Arcane", "properties": {"spell_defense": {"ac": 5, "save_advantage": "DEX"}, "uses": "1/long rest", "action_type": "reaction"}}, {"name": "Ochre Warden Wall", "armor_type": "shield", "ac_bonus": 4, "con_cap": null, "stealth_disadvantage": true, "strength_req": 15, "description": "A great rectangular shield of ochre-banded steel. Allies adjacent to you gain +1 AC against ranged attacks.", "rarity": "Arcane", "properties": {"aura_ac_vs_ranged": {"range_ft": 5, "bonus": 1}}}, {"name": "Radiant Haloshield", "armor_type": "shield", "ac_bonus": 4, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "Disc shield ringed by a faint halo. Twice per long rest, as a reaction when a creature within 30 ft is hit, grant it +3 AC against that attack, possibly turning it into a miss.", "rarity": "Mythical", "properties": {"ally_ac_reaction": {"range_ft": 30, "bonus": 3}, "uses": "2/long rest", "action_type": "reaction"}}, {"name": "Graniar Oathstone", "armor_type": "shield", "ac_bonus": 4, "con_cap": null, "stealth_disadvantage": true, "strength_req": 15, "description": "Shield cut from a stone sworn upon by Graniar elders. You have advantage on STR and CON saves while the shield is held.", "rarity": "Mythical", "properties": {"save_advantage": ["STR", "CON"]}}, {"name": "Bulwark of the Hollow Sky", "armor_type": "shield", "ac_bonus": 5, "con_cap": null, "stealth_disadvantage": false, "strength_req": null, "description": "A sky-pale shield that weighs nothing. Once per long rest, as a reaction, you and allies within 10 ft are immune to all damage from one attack or effect. You can't be flanked.", "rarity": "Blessed", "properties": {"aura_negate": {"range_ft": 10}, "uses": "1/long rest", "action_type": "reaction", "flank_immune": true}}]$armor$::jsonb)
  AS r(name text, armor_type text, ac_bonus int, con_cap int, stealth_disadvantage bool, strength_req int, description text, rarity text, properties jsonb)
WHERE NOT EXISTS (SELECT 1 FROM armor a WHERE lower(a.name) = lower(r.name));
COMMIT;
